let curQ = 0, score = 0, answered = false;

/* ====== PARTICLES ====== */
function initParticles() {
  const canvas = document.getElementById("particles");
  const ctx = canvas.getContext("2d");
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
  const pts = [];
  const n = Math.min(55, Math.floor(window.innerWidth / 20));
  for (let i = 0; i < n; i++) pts.push({
    x: Math.random() * canvas.width, y: Math.random() * canvas.height,
    r: Math.random() * 1.4 + 0.3,
    dx: (Math.random() - .5) * .35, dy: (Math.random() - .5) * .35,
    a: Math.random() * .45 + .05
  });
  function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    const isDark = document.documentElement.getAttribute("data-theme") === "dark";
    pts.forEach(p => {
      ctx.beginPath(); ctx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
      ctx.fillStyle = isDark
        ? `rgba(0,200,255,${p.a})`
        : `rgba(0,80,200,${p.a * .35})`;
      ctx.fill();
      p.x += p.dx; p.y += p.dy;
      if (p.x < 0 || p.x > canvas.width) p.dx *= -1;
      if (p.y < 0 || p.y > canvas.height) p.dy *= -1;
    });
    requestAnimationFrame(draw);
  }
  draw();
  window.addEventListener("resize", () => {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
  });
}
window.addEventListener("load", initParticles);

/* ====== THEME ====== */
function toggleTheme() {
  const html = document.documentElement;
  const t = html.getAttribute("data-theme") === "dark" ? "light" : "dark";
  html.setAttribute("data-theme", t);
  localStorage.setItem("emcy-theme", t);
}
(function () {
  const s = localStorage.getItem("emcy-theme");
  if (s) document.documentElement.setAttribute("data-theme", s);
})();

/* ====== NAVIGATION ====== */
function showPage(id) {
  document.querySelectorAll(".page").forEach(p => p.classList.remove("active"));
  document.getElementById(id).classList.add("active");
  window.scrollTo({ top: 0, behavior: "smooth" });
}

function startQuiz() {
  curQ = 0; score = 0; answered = false;
  document.getElementById("live-score").textContent = "0";
  showPage("quiz");
  loadQuestion();
}

/* ====== QUIZ ====== */
function loadQuestion() {
  answered = false;
  const q = questions[curQ], total = questions.length;
  document.getElementById("q-current").textContent = curQ + 1;
  document.getElementById("q-total").textContent = total;
  document.getElementById("progress-bar").style.width = ((curQ / total) * 100) + "%";
  document.getElementById("q-category").textContent = q.category;
  document.getElementById("q-text").textContent = q.text;

  const grid = document.getElementById("options-grid");
  grid.innerHTML = "";
  ["A","B","C","D"].forEach((l, i) => {
    const btn = document.createElement("button");
    btn.className = "option-btn";
    btn.innerHTML = `<span class="option-letter">${l}</span>${q.options[i]}`;
    btn.onclick = () => selectAnswer(i, btn);
    grid.appendChild(btn);
  });

  const fb = document.getElementById("feedback-box");
  fb.className = "feedback-box"; fb.textContent = "";
  const nb = document.getElementById("btn-next");
  nb.style.display = "none";
  document.getElementById("next-label").textContent =
    curQ === total - 1 ? "Voir mes résultats" : "Question suivante";

  const card = document.getElementById("question-card");
  card.style.animation = "none"; void card.offsetWidth;
  card.style.animation = "cardIn .4s var(--ease-smooth)";
}

function selectAnswer(idx, btn) {
  if (answered) return;
  answered = true;
  const q = questions[curQ];
  document.querySelectorAll(".option-btn").forEach(b => b.disabled = true);
  const fb = document.getElementById("feedback-box");
  if (idx === q.correct) {
    score++;
    btn.classList.add("correct");
    fb.className = "feedback-box correct-fb show";
    fb.textContent = q.explanation;
    const sv = document.getElementById("live-score");
    sv.textContent = score;
    sv.classList.remove("score-pulse"); void sv.offsetWidth; sv.classList.add("score-pulse");
  } else {
    btn.classList.add("wrong");
    document.querySelectorAll(".option-btn")[q.correct].classList.add("correct");
    fb.className = "feedback-box wrong-fb show";
    fb.textContent = "\u274C " + q.explanation;
  }
  document.getElementById("btn-next").style.display = "flex";
}

function nextQuestion() {
  curQ++;
  if (curQ >= questions.length) showResults(); else loadQuestion();
}

/* ====== RESULTS ====== */
function showResults() {
  showPage("results");
  animCount(0, score, 900, v => document.getElementById("result-score-num").textContent = v);

  const card = document.getElementById("result-card");
  let cls, icon, level, msg, tips;

  if (score >= 8) {
    cls = "level-smart"; icon = "\uD83D\uDEE1\uFE0F";
    level = "Cyber Smart \uD83D\uDE80";
    msg = "Bravo ! Tu as d'excellentes pratiques num\u00E9riques. Tu es un vrai ambassadeur de la cybers\u00E9curit\u00E9. Continue \u00E0 te former et sensibiliser ton entourage !";
    tips = ["Partage tes connaissances","Reste vigilant(e)","Accompagne les autres"];
  } else if (score >= 5) {
    cls = "level-risk"; icon = "\u26A0\uFE0F";
    level = "\u00C0 risque \u26A0\uFE0F";
    msg = "Tu as des bases, mais tu peux am\u00E9liorer ta s\u00E9curit\u00E9 en ligne. Quelques mauvaises habitudes peuvent t'exposer. Approfondis tes connaissances !";
    tips = ["Renforce tes mots de passe","M\u00E9fie-toi du phishing","Active le 2FA"];
  } else {
    cls = "level-vulnerable"; icon = "\uD83D\uDEA8";
    level = "Vuln\u00E9rable \uD83D\uDD34";
    msg = "Attention ! Tu es expos\u00E9(e) aux risques en ligne. Il est urgent d'apprendre les bonnes pratiques num\u00E9riques. Parles-en avec un adulte de confiance !";
    tips = ["Apprends les bases","Parles-en \u00E0 un adulte","Rejoins une formation digitale"];
  }

  card.className = "result-card " + cls;
  document.getElementById("result-icon").textContent = icon;
  document.getElementById("result-level").textContent = level;
  document.getElementById("result-message").textContent = msg;
  document.getElementById("result-tips").innerHTML =
    tips.map((t, i) => `<span class="tip-pill" style="animation-delay:${i * .1}s">\uD83D\uDCA1 ${t}</span>`).join("");

  const bw = document.getElementById("badge-section");
  if (score >= 7) { bw.style.display = "block"; setTimeout(() => drawBadge(score), 400); }
  else bw.style.display = "none";
}

function animCount(from, to, dur, cb) {
  const start = performance.now();
  function up(t) {
    const p = Math.min((t - start) / dur, 1);
    cb(Math.round(from + (to - from) * (1 - Math.pow(1 - p, 3))));
    if (p < 1) requestAnimationFrame(up);
  }
  requestAnimationFrame(up);
}

/* ====== BADGE ====== */
function drawBadge(sc) {
  const cv = document.getElementById("badge-canvas");
  const ctx = cv.getContext("2d");
  const W = 500, H = 500;
  cv.width = W; cv.height = H;

  // Background
  const bg = ctx.createLinearGradient(0, 0, W, H);
  bg.addColorStop(0, "#030914"); bg.addColorStop(.5, "#071428"); bg.addColorStop(1, "#040e20");
  ctx.fillStyle = bg; ctx.fillRect(0, 0, W, H);

  // Hex grid
  ctx.strokeStyle = "rgba(0,180,255,0.06)"; ctx.lineWidth = 1;
  for (let row = -1; row < H / 34 + 1; row++) {
    for (let col = -1; col < W / 30 + 1; col++) {
      const hx = col * 30, hy = row * 34 + (col % 2 === 1 ? 17 : 0);
      ctx.beginPath();
      for (let k = 0; k < 6; k++) {
        const a = (Math.PI / 180) * (60 * k - 30);
        ctx.lineTo(hx + 16 * Math.cos(a), hy + 16 * Math.sin(a));
      }
      ctx.closePath(); ctx.stroke();
    }
  }

  // Glow center
  const rg = ctx.createRadialGradient(W/2,H/2,50,W/2,H/2,230);
  rg.addColorStop(0,"rgba(0,100,255,0.1)"); rg.addColorStop(1,"transparent");
  ctx.fillStyle = rg; ctx.fillRect(0, 0, W, H);

  // Outer ring
  ctx.beginPath(); ctx.arc(W/2, H/2, 222, 0, Math.PI*2);
  const ring = ctx.createLinearGradient(W/2-222,H/2,W/2+222,H/2);
  ring.addColorStop(0,"rgba(0,80,255,0.4)"); ring.addColorStop(.5,"rgba(0,200,255,0.7)"); ring.addColorStop(1,"rgba(0,80,255,0.4)");
  ctx.strokeStyle = ring; ctx.lineWidth = 1.5; ctx.stroke();

  // Score arc
  ctx.beginPath(); ctx.arc(W/2,H/2,222,-Math.PI/2,-Math.PI/2+(sc/10)*2*Math.PI);
  const ag = ctx.createLinearGradient(W/2-222,H/2,W/2+222,H/2);
  ag.addColorStop(0,"#0044cc"); ag.addColorStop(1,"#00c8ff");
  ctx.strokeStyle=ag; ctx.lineWidth=5; ctx.lineCap="round"; ctx.stroke();

  // Inner dashed
  ctx.beginPath(); ctx.arc(W/2,H/2,207,0,Math.PI*2);
  ctx.strokeStyle="rgba(0,200,255,0.07)"; ctx.lineWidth=1; ctx.setLineDash([4,4]); ctx.stroke(); ctx.setLineDash([]);

  // Load logo
  const img = new Image();
  img.onload = function() {
    ctx.save();
    ctx.drawImage(img, W/2 - 115, 105, 230, 112);
    ctx.restore();
    finishBadge(ctx, W, H, sc);
  };
  img.onerror = function() { finishBadge(ctx, W, H, sc); };
  img.src = "data:image/png;base64," + LOGO_B64;
}

function finishBadge(ctx, W, H, sc) {
  // Shield
  ctx.save(); ctx.translate(W/2, 262);
  const s = 32;
  ctx.beginPath();
  ctx.moveTo(0,-s); ctx.bezierCurveTo(s*.7,-s,s,-s*.4,s,0);
  ctx.bezierCurveTo(s,s*.6,0,s*1.1,0,s*1.1);
  ctx.bezierCurveTo(0,s*1.1,-s,s*.6,-s,0);
  ctx.bezierCurveTo(-s,-s*.4,-s*.7,-s,0,-s); ctx.closePath();
  const sg = ctx.createLinearGradient(-s,-s,s,s);
  sg.addColorStop(0,"rgba(0,80,255,0.55)"); sg.addColorStop(1,"rgba(0,180,255,0.4)");
  ctx.fillStyle = sg; ctx.fill();
  ctx.strokeStyle = "#00c8ff"; ctx.lineWidth = 2;
  ctx.shadowColor = "#00c8ff"; ctx.shadowBlur = 12; ctx.stroke(); ctx.shadowBlur = 0;
  // Checkmark
  ctx.beginPath();
  ctx.moveTo(-s*.32,s*.1); ctx.lineTo(-s*.05,s*.4); ctx.lineTo(s*.38,-s*.2);
  ctx.strokeStyle = "#00c8ff"; ctx.lineWidth = s * .1; ctx.lineCap = "round"; ctx.lineJoin = "round";
  ctx.shadowColor = "#00c8ff"; ctx.shadowBlur = 10; ctx.stroke(); ctx.shadowBlur = 0;
  ctx.restore();

  // Title
  ctx.font = "bold 30px Orbitron,sans-serif"; ctx.textAlign = "center";
  ctx.fillStyle = "#ffffff"; ctx.shadowColor = "#0066ff"; ctx.shadowBlur = 16;
  ctx.fillText("I'M CYBER SAFE", W/2, 334); ctx.shadowBlur = 0;

  // Divider
  ctx.beginPath(); ctx.moveTo(W/2-95,347); ctx.lineTo(W/2+95,347);
  const dg = ctx.createLinearGradient(W/2-95,347,W/2+95,347);
  dg.addColorStop(0,"transparent"); dg.addColorStop(.5,"rgba(0,200,255,0.6)"); dg.addColorStop(1,"transparent");
  ctx.strokeStyle = dg; ctx.lineWidth = 1; ctx.stroke();

  // Score
  ctx.font = "bold 22px Orbitron,sans-serif";
  ctx.fillStyle = "#00c8ff"; ctx.shadowColor = "#00c8ff"; ctx.shadowBlur = 10;
  ctx.fillText(sc + " / 10", W/2, 374); ctx.shadowBlur = 0;

  // Certified
  ctx.font = "500 11px Exo 2,sans-serif";
  ctx.fillStyle = "rgba(160,200,255,0.65)";
  ctx.fillText("CERTIFIED BY EMCY", W/2, 398);

  // Sub-line
  ctx.font = "400 10px Exo 2,sans-serif";
  ctx.fillStyle = "rgba(120,160,220,0.4)";
  ctx.fillText("Jeunes-Espace Maroc Cyberconfiance", W/2, 420);

  // Corners
  [[28,28,1,1],[W-28,28,-1,1],[28,H-28,1,-1],[W-28,H-28,-1,-1]].forEach(([x,y,dx,dy]) => {
    ctx.beginPath(); ctx.moveTo(x+18*dx,y); ctx.lineTo(x,y); ctx.lineTo(x,y+18*dy);
    ctx.strokeStyle = "rgba(0,180,255,0.5)"; ctx.lineWidth = 2; ctx.lineCap = "square"; ctx.stroke();
  });
}

function downloadBadge() {
  const cv = document.getElementById("badge-canvas");
  const a = document.createElement("a");
  a.download = "badge-cyber-safe-emcy.png";
  a.href = cv.toDataURL("image/png"); a.click();
}

function restartQuiz() { curQ = 0; score = 0; answered = false; showPage("home"); }

function shareResult() {
  const lv = score >= 8 ? "Cyber Smart" : score >= 5 ? "A risque" : "Vulnerable";
  const txt = "\uD83D\uDEE1\uFE0F Test Niveau Digital \u2013 EMCY\n\uD83D\uDCCA Score : " + score + "/10\n\uD83C\uDFF7\uFE0F Niveau : " + lv + "\n\nTeste-toi aussi !";
  if (navigator.share) navigator.share({ title: "Test Niveau Digital \u2013 EMCY", text: txt });
  else if (navigator.clipboard) navigator.clipboard.writeText(txt).then(() => alert("\u2705 R\u00E9sultat copi\u00E9 !"));
  else alert(txt);
}
